query:
UPDATE packages SET usedHours = (
  SELECT COALESCE(SUM(a.durationMinutes), 0)
  FROM attendances a
  WHERE a.packageId = 720003 AND a.durationMinutes IS NOT NULL
)
WHERE id = 720003;

UPDATE residents SET outOfPackageMinutes = 0 WHERE id = 60001;

SELECT p.id, p.totalHours, p.usedHours, r.outOfPackageMinutes
FROM packages p JOIN residents r ON r.id = p.residentId
WHERE p.id = 720003;

